package br.gov.dere.application.access;
import br.gov.dere.persistence.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AccessService { private final DereUserRepository users; private final DereEntityRepository entities; private final PasswordEncoder encoder; public AccessService(DereUserRepository u,DereEntityRepository e,PasswordEncoder p){users=u;entities=e;encoder=p;} public DereUserEntity user(Long id){return users.findById(id).orElseThrow();} public DereUserEntity userByLogin(String l){return users.findByLogin(l).orElseThrow();} public DereEntityEntity entity(Long id){return entities.findById(id).orElseThrow();} public void assertAccess(Long uid,Long eid){var u=user(uid);if(u.isMaster())return;if(u.getEntities().stream().noneMatch(x->x.getId().equals(eid)))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Usuário não associado à entidade");} public DereUserEntity create(String l,String pass,String name){return users.save(new DereUserEntity(l,encoder.encode(pass),name));} public String encode(String pass){return encoder.encode(pass);} public boolean login(String l,String p){var u=users.findByLogin(l).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.UNAUTHORIZED,"Login inválido"));return encoder.matches(p,u.getPasswordHash());} }
